  /**
   * The AI agent to use for task completion. Defaults to browser-use.
   */
  agent?: 'browser-use' | 'openai-cua' | 'gemini-computer-use' | 'anthropic-cua' | 'yutori';
  /**
   * The AI provider to use for task completion.
   */
  provider?: 'openai' | 'gemini' | 'groq' | 'azure' | 'xai';
  /**
   * The specific model to use for task completion. see our [models](/agentic-browser-control/ai-task-completion#available-models) page for more information.
   */
  model?: string;
  /**
   * Enable element detection for better interaction accuracy. Improves the agent's ability to identify and interact with UI elements.
   */
  detect_elements?: boolean;
  /**
   * Allow human intervention during task execution. When enabled, the agent can request human input for ambiguous situations.
   */
  human_intervention?: boolean;
  /**
   * Maximum number of steps the agent can take to complete the task. Defaults to 200.
   */
  max_steps?: number;
  /**
   * Timeout in seconds for each LLM call made by the agent (browser-use agent only). Raise it when tasks with deep context (long histories, large pages) hit LLM call timeouts. When omitted, the agent uses its model-based defaults.
   */
